		deleteGenerationIds: readonly GenerationId[];
		expectedBaseExpectedHead: ExpectedHead;
		generationId: GenerationId;
		replacementBaseExpectedHead: Readonly<{ kind: "none"; objectId: StorageObjectId }>;
	}>;
	objectId: StorageObjectId;
